    "outlook": "【A股盘面】9/21 A股平开高走、个股普涨：沪指平开0.21%收+0.97%、深成平开0.55%收+0.65%、创业板平开0.93%收+0.80%、科创50平开1.0%(临界)收+0.29%、上证50平开0.35%收+0.90%，五大指数均平开高走。全市场4536涨/936跌、涨停103、成交约2.03万亿放量。医疗服务(诺禾致源20cm、南华生物涨停)高开高走、房产经纪(世联行/我爱我家涨停)低开高走、会展/宠物食品/防水材料平开高走；空调平开低走、黄金/贵金属/白银/钨走弱，呈医药地产消费强、资源家电弱结构。\n【资金与结构】主力净流入医药生物+67.4亿、化学制剂+28亿、化学制药+27.6亿居前；净流出半导体-49.8亿、电子-43亿、集成电路封测-27.7亿。资金高低切：从上周五领涨的半导体/电子获利了结，集中涌入医药(医疗服务/CXO)、地产链与消费，结构性强势切换清晰。\n【AI预测】今日6项预测仅2项命中：创新药/CRO(偏强→医疗服务+7.97%✓)、大金融(走强→银行保险受3000亿注资驱动偏多✓)兑现；国产算力/存储(走强/偏强→半导体净流出近50亿、板块约-0.79%✗)、AI应用(偏强→未匹配到对应板块涨跌幅✗)、商业航天/核电(承压→缺乏明确负向板块✗)未兑现。属风格高低切：资金从科技切至医药地产，AI主线短期背离但产业趋势未逆转。后续确认：医药地产持续性、半导体能否止跌回稳。\n【板块轮动与机会】低位轮动与政策驱动并行：①医疗服务/CXO(医药十五五规划，研发CAPEX长周期)；②房产经纪/地产链(存量时代政策托底)；③会展/宠物/防水(消费与后周期修复)；④电网设备(AI算力用电)。防御看高股息银行(注资利好)。\n【风险与避险】美联储加息落地后美元仍强压制黄金与估值；美伊制裁法案、中东油价反复构成外部扰动；回避今日走弱的空调/贵金属/小金属及半导体高位分歧品种；节前控仓不追一致板，待量能确认再上主线。",
